_ITEMS = sorted(_EN.items(), key=lambda pair: len(pair[0]), reverse=True)
# Match only Ukrainian tokens for single-word substitutions; longer phrases can
# be safely replaced within dynamic strings such as "📍 Вибрано: ...".

def translate(value: str, lang: str = 'en') -> str:
    if lang != 'en' or not isinstance(value, str) or not re.search(r'[А-Яа-яІіЇїЄєҐґ]',value):
        return value
    if value in _EN:
        return _EN[value]
    text=value
    # Replace whole terms only; a term such as 'Марс' must not turn
    # 'Марса' into mixed-script 'Marsа'.
    alphabet = r"A-Za-zА-Яа-яІіЇїЄєҐґ"
    for uk,en in _ITEMS:
        if uk not in text:
            continue
        left = f"(?<![{alphabet}])" if uk[0].isalpha() else ""
        right = f"(?![{alphabet}])" if uk[-1].isalpha() else ""
        text = re.sub(left + re.escape(uk) + right, lambda _: en, text)
    return text

class LocalizedStreamlit:
    """Translate visible Streamlit text, while keeping widget option IDs intact."""
    METHODS={
        'title','header','subheader','caption','write','markdown','info','warning','error',
        'success','metric','button','link_button','download_button','form_submit_button',
        'radio','selectbox','slider','number_input','text_input','toggle','checkbox',
        'expander','spinner','file_uploader','multiselect','text_area','select_slider',
        'dataframe','status','toast','code'
    }
    LABEL_FIRST={'title','header','subheader','caption','markdown','info','warning',
                 'error','success','metric','button','link_button','download_button',
                 'form_submit_button','radio','selectbox','slider','number_input',
                 'text_input','toggle','checkbox','expander','spinner','file_uploader',
                 'multiselect','text_area','select_slider','status','toast'}
    def __init__(self, real): self._real=real
    def __getattr__(self, name):
        item=getattr(self._real,name)
        if name not in self.METHODS or not callable(item):return item
        def localized(*args,**kwargs):
            lang=self._real.session_state.get('tt_lang','en')
            if lang!='en':return item(*args,**kwargs)
            args=list(args)
            if name in ('radio','selectbox','multiselect','select_slider'):
                user_format=kwargs.get('format_func')
                kwargs['format_func']=(lambda option, previous=user_format:
                    translate(str(previous(option) if previous else option),'en'))
            if name=='write':
                args=[translate(x,lang) if isinstance(x,str) else x for x in args]
            elif args and name in self.LABEL_FIRST and isinstance(args[0],str):
                args[0]=translate(args[0],lang)
            elif name=='code':
                # Code/URLs must be preserved byte-for-byte.
                pass
            if name=='metric' and len(args)>1 and isinstance(args[1],str):
                args[1]=translate(args[1],lang)
            if name=='dataframe' and args:
                try:
                    import pandas as pd
                    if isinstance(args[0],pd.DataFrame):
                        frame=args[0].copy()
                        frame=frame.rename(columns=lambda c: translate(c,lang) if isinstance(c,str) else c)
                        if len(frame)<=75:
                            for col in frame.select_dtypes(include=['object','string']).columns:
                                frame[col]=frame[col].map(lambda v:translate(v,lang) if isinstance(v,str) and len(v)<2000 else v)
                        args[0]=frame
                except (TypeError,ValueError,ImportError):
                    pass
            return item(*args,**kwargs)
        return localized
